<?php
declare(strict_types=1);
session_start();
require_once __DIR__ . '/includes/access.php';
require_once __DIR__ . '/../db.php';
require_once __DIR__ . '/includes/billing-adjustments.php';
tdc_require_access();
$ref = preg_replace('/[^A-Za-z0-9_-]/', '', (string)($_GET['ref'] ?? ''));
$q=$pdo->prepare('SELECT v.*,p.PatientName,p.PatientPhone,p.PatientAddress,d.DoctorName FROM visits v JOIN patients p ON p.PatientID=v.PatientID LEFT JOIN doctors d ON d.DoctorID=v.DoctorID WHERE v.VisitReference=?'); $q->execute([$ref]); $v=$q->fetch(); if(!$v){http_response_code(404);exit('Consultation receipt not found.');}
$adj=tdc_load_bill_adjustment($pdo,'consultation',(string)$v['VisitReference']); $final=$adj?(float)$adj['FinalAmount']:(float)$v['ConsultationFee']; $gross=$adj?(float)$adj['GrossAmount']:$final; $discount=$adj?(float)$adj['DiscountAmount']:0; $subtotal=max(0,$gross-$discount); $tax=$adj?(float)$adj['TaxAmount']:0; $paid=(float)$v['AmountPaid']; $due=(float)$v['DueBalance']; $h=$pdo->query('SELECT CompanyName,PhoneNumbers,CompanyAddress,CompanyLogo FROM prescriptionsheader LIMIT 1')->fetch()?:[]; $e=static fn($x)=>htmlspecialchars((string)$x,ENT_QUOTES,'UTF-8');
?><!doctype html><html><head><meta charset="utf-8"><title>Consultation Receipt <?= $e($ref) ?></title><style>@page{size:A4;margin:14mm}*{box-sizing:border-box}body{font:13px Arial;color:#172033;background:#f1f3f8;margin:0}.sheet{width:210mm;min-height:297mm;margin:12px auto;background:#fff;padding:18mm;border:1px solid #d7dced}.head{display:flex;gap:16px;border-bottom:3px solid #303192;padding:10px 0 16px;align-items:center}.head img{width:68px;height:68px;object-fit:contain}.name{font-size:25px;font-weight:700;color:#303192}.label{margin-left:auto;text-align:right;color:#303192;font-weight:700}.meta{display:grid;grid-template-columns:1fr 1fr;gap:8px 24px;background:#f6f7fc;border:1px solid #d7dced;padding:14px;margin-top:20px}.meta b{display:inline-block;width:100px;color:#59647a;font-size:11px;text-transform:uppercase}h1{color:#14265f;font-size:21px}table{width:100%;border-collapse:collapse;margin-top:18px}th,td{border:1px solid #cfd5e4;padding:10px;text-align:left}th{background:#eef1f8;color:#303192}.money{width:300px;margin:18px 0 0 auto}.money div{display:flex;justify-content:space-between;border-bottom:1px solid #e0e3eb;padding:7px}.money .final{font-weight:700;color:#303192;border-top:2px solid #303192}.reason{margin-top:18px;padding:10px;background:#f6f7fc}.print{float:right;background:#303192;color:#fff;border:0;padding:10px 18px}@media print{body{background:#fff}.print{display:none}.sheet{margin:0;border:0;width:100%}}</style></head><body><button class="print" onclick="window.print()">Print A4</button><main class="sheet"><header class="head"><img src="<?= $e($h['CompanyLogo']??'uploads/tareydermacliniclogo.png') ?>"><div><div class="name"><?= $e($h['CompanyName']??'Tarey Derma Clinic') ?></div><div><?= $e($h['CompanyAddress']??'') ?> · <?= $e($h['PhoneNumbers']??'') ?></div></div><div class="label">CONSULTATION<br>RECEIPT</div></header><h1>Consultation Billing Receipt</h1><section class="meta"><div><b>Visit Reference</b><?= $e($v['VisitReference']) ?></div><div><b>Date</b><?= $e(date('d/m/Y H:i',strtotime((string)$v['VisitDate']))) ?></div><div><b>Patient</b><?= $e($v['PatientName']) ?></div><div><b>Phone</b><?= $e($v['PatientPhone'] ?: 'Not recorded') ?></div><div><b>Doctor</b><?= $e($v['DoctorName']??'') ?></div><div><b>Address</b><?= $e($v['PatientAddress']??'') ?></div></section><table><tr><th>Description</th><th>Amount</th></tr><tr><td>Consultation</td><td><?= number_format($gross,2) ?></td></tr></table><section class="money"><div><span>Gross Amount</span><span><?= number_format($gross,2) ?></span></div><div><span>Discount</span><span><?= number_format($discount,2) ?></span></div><div><span>Subtotal</span><span><?= number_format($subtotal,2) ?></span></div><div><span>Tax</span><span><?= number_format($tax,2) ?></span></div><div class="final"><span>Final Amount</span><span><?= number_format($final,2) ?></span></div><div><span>Paid</span><span><?= number_format($paid,2) ?></span></div><div><span>Balance Due</span><span><?= number_format($due,2) ?></span></div><div><span>Payment Status</span><span><?= $e($v['PaymentStatus']) ?></span></div></section><?php if($adj&&trim((string)$adj['DiscountReason'])!==''): ?><div class="reason"><b>Discount Reason:</b> <?= $e($adj['DiscountReason']) ?></div><?php endif; ?></main></body></html>
